#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-05-06

# Density ratchet: info / (info + decoration + ws) >= 0.20 per fenced ASCII
# block in src/skills/**/SKILL.md (mirrors ascii-lint density-min rule).
# Existing exceptions live in ascii-density-baseline.tsv and may only shrink.

set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$ROOT"
SKILLS_DIR="$ROOT/src/skills"
BASELINE="$ROOT/tests/unit/ascii-density-baseline.tsv"
BASELINE_REL="tests/unit/ascii-density-baseline.tsv"
THRESHOLD="0.20"

checked=0
low=0
SCAN_ONLY=false

case "${1:-}" in
  "") ;;
  --scan) SCAN_ONLY=true ;;
  *) echo "usage: $0 [--scan]" >&2; exit 2 ;;
esac
[ "$#" -le 1 ] || { echo "usage: $0 [--scan]" >&2; exit 2; }

DENSITY_TMP="$(mktemp -d "${TMPDIR:-/tmp}/ork-ascii-density.XXXXXX")"
OBSERVED="$DENSITY_TMP/observed.tsv"
REFERENCE_OBSERVED="$DENSITY_TMP/reference-observed.tsv"
REFERENCE_BASELINE="$DENSITY_TMP/reference-baseline.tsv"
trap 'rm -rf "$DENSITY_TMP"' EXIT

fail_closed() {
  echo "FAILED: invalid ASCII density baseline: $1" >&2
  exit 1
}

validate_baseline() {
  local baseline="$1"
  [ -f "$baseline" ] || fail_closed "missing $baseline"
  [ "$(head -n 1 "$baseline")" = '# ascii-density-baseline/1' ] || fail_closed "missing schema header"

  local path allowed extra
  while IFS=$'\t' read -r path allowed extra; do
    case "$path" in
      ""|\#*) continue ;;
      src/skills/*/SKILL.md) ;;
      *) fail_closed "invalid path '$path'" ;;
    esac
    [ -z "${extra:-}" ] || fail_closed "too many fields for '$path'"
    case "$allowed" in
      ""|*[!0-9]*) fail_closed "invalid count '$allowed' for '$path'" ;;
    esac
    if awk -F $'\t' -v path="$path" '$1 == path { found++ } END { exit found > 1 ? 0 : 1 }' "$baseline"; then
      fail_closed "duplicate path '$path'"
    fi
  done < "$baseline"
}

# Resolve the interpreter ONCE, past any version-manager shim (168 ms per
# spawn through pyenv vs 22 ms direct, measured 2026-09-12). Only density()
# still spawns python, and only for box-heavy blocks (25 of 637).
PY3="$(command -v pyenv >/dev/null 2>&1 && pyenv which python3 2>/dev/null || command -v python3)"

# Density: info / (info + box + ws). The block arrives as $1, not on stdin.
# The old form was `printf block | python3 - <<'EOF'`: the heredoc REPLACED
# stdin, so sys.stdin.read() returned the empty string, every block scored
# 1.000, and this gate had never failed anything. A dead gate that reports
# OK is worse than no gate; see the awk comparison below, which now bites.
density() {
  "$PY3" -c '
import sys, re
text = sys.argv[1]
info = len(re.findall(r"[A-Za-z0-9→←↑↓]", text))
boxes = sum(1 for c in text if 0x2500 <= ord(c) <= 0x257F)
ws = sum(1 for c in text if c.isspace())
total = info + boxes + ws
print(f"{(info/total) if total else 1.0:.3f}")
' "$1"
}

# Count Unicode Box-Drawing chars (U+2500-U+257F) in pure bash: strip every
# character outside the range, measure what is left. Zero spawns. This runs
# once per fenced block (637 across 107 skills); as a python3 spawn it cost
# 30s direct and minutes through a pyenv shim, which made the pre-push unit
# phase read as a hang (2026-09-12). Needs a UTF-8 locale, which the
# ${#chars} / ${chars:$i:1} arithmetic in this file already assumes.
count_box() {
  local stripped="${1//[^─-╿]/}"
  printf '%s\n' "${#stripped}"
}

scan_file() {
  local file="$1"
  local stable_path="${2:-${file#$ROOT/}}"
  local report="${3:-true}"
  local in_block=0
  local block=""
  local startline=0
  local lineno=0
  while IFS= read -r line; do
    lineno=$((lineno + 1))
    if [ "$in_block" = 0 ]; then
      case "$line" in '```'*) in_block=1; block=""; startline=$((lineno + 1)) ;; esac
    else
      case "$line" in
        '```'*)
          local box_count
          box_count=$(count_box "$block")
          if [ "${box_count:-0}" -ge 3 ]; then
            checked=$((checked + 1))
            local d
            d=$(density "$block")
            if awk -v d="$d" -v t="$THRESHOLD" 'BEGIN{ exit (d < t) ? 0 : 1 }'; then
              if [ "$report" = true ]; then
                printf '⚠ %s:%d density %s < %s\n' "$stable_path" "$startline" "$d" "$THRESHOLD"
              fi
              printf '%s\t%s\t%s\n' "$stable_path" "$startline" "$d" >> "$OBSERVED"
              low=$((low + 1))
            fi
          fi
          in_block=0
          ;;
        *) block+="$line"$'\n' ;;
      esac
    fi
  done < "$file"
}

reference_baseline() {
  local base_ref path file n=0 previous_observed
  if [ -n "${ASCII_DENSITY_BASE_REF:-}" ]; then
    base_ref="$ASCII_DENSITY_BASE_REF"
  elif ! base_ref=$(git merge-base HEAD origin/main 2>/dev/null); then
    fail_closed "cannot resolve merge-base HEAD origin/main"
  fi
  git rev-parse --verify -q "${base_ref}^{commit}" >/dev/null 2>&1 || \
    fail_closed "invalid reference '$base_ref'"

  if git cat-file -e "$base_ref:$BASELINE_REL" 2>/dev/null; then
    git show "$base_ref:$BASELINE_REL" > "$REFERENCE_BASELINE" || \
      fail_closed "cannot read reference baseline at $base_ref"
    validate_baseline "$REFERENCE_BASELINE"
    return
  fi

  previous_observed="$OBSERVED"
  OBSERVED="$REFERENCE_OBSERVED"
  : > "$REFERENCE_OBSERVED"
  checked=0
  low=0
  while IFS= read -r path; do
    case "$path" in src/skills/*/SKILL.md) ;; *) continue ;; esac
    file="$DENSITY_TMP/reference-$n.md"
    n=$((n + 1))
    git show "$base_ref:$path" > "$file" || fail_closed "cannot read $path at $base_ref"
    scan_file "$file" "$path" false
  done < <(git ls-tree -r --name-only "$base_ref" -- src/skills)

  printf '%s\n' '# ascii-density-baseline/1' > "$REFERENCE_BASELINE"
  cut -f1 "$REFERENCE_OBSERVED" 2>/dev/null | sort -u | while IFS= read -r path; do
    [ -n "$path" ] || continue
    allowed=$(awk -F $'\t' -v path="$path" '$1 == path { count++ } END { print count + 0 }' "$REFERENCE_OBSERVED")
    printf '%s\t%s\n' "$path" "$allowed"
  done >> "$REFERENCE_BASELINE"
  validate_baseline "$REFERENCE_BASELINE"
  OBSERVED="$previous_observed"
}

enforce_monotonic_baseline() {
  local path allowed extra reference_allowed
  while IFS=$'\t' read -r path allowed extra; do
    case "$path" in ""|\#*) continue ;; esac
    reference_allowed=$(awk -F $'\t' -v path="$path" '$1 == path { print $2 }' "$REFERENCE_BASELINE")
    reference_allowed="${reference_allowed:-0}"
    if [ "$allowed" -gt "$reference_allowed" ]; then
      echo "FAILED: baseline allowance for $path is $allowed, reference allows $reference_allowed; baseline may only lower" >&2
      exit 1
    fi
  done < "$BASELINE"
}

if ! $SCAN_ONLY; then
  validate_baseline "$BASELINE"
  reference_baseline
  enforce_monotonic_baseline
  checked=0
  low=0
  : > "$OBSERVED"
fi

for file in "$SKILLS_DIR"/*/SKILL.md; do
  [ -f "$file" ] || continue
  scan_file "$file"
done

printf '\n✓ scanned %d block(s) · ⚠ %d below %s\n' "$checked" "$low" "$THRESHOLD"

if $SCAN_ONLY; then
  echo "SCAN ONLY: baseline ratchet not evaluated"
  exit 0
fi

baseline_total=$(awk -F $'\t' '/^[^#[:space:]]/ { total += $2 } END { print total + 0 }' "$BASELINE")
if [ "$low" -gt "$baseline_total" ]; then
  echo "FAILED: total low-density blocks $low exceeds baseline $baseline_total" >&2
  exit 1
fi

failed=0
for path in $(cut -f1 "$OBSERVED" | sort -u); do
  allowed=$(awk -F $'\t' -v path="$path" '$1 == path { print $2 }' "$BASELINE")
  actual=$(awk -F $'\t' -v path="$path" '$1 == path { count++ } END { print count + 0 }' "$OBSERVED")
  if [ -z "$allowed" ]; then
    echo "FAILED: new low-density block in $path ($actual block(s)); baseline may only shrink" >&2
    failed=1
  elif [ "$actual" -gt "$allowed" ]; then
    echo "FAILED: $path has $actual low-density block(s), baseline allows $allowed" >&2
    failed=1
  fi
done

[ "$failed" -eq 0 ] || exit 1
exit 0
